import pickle

def add_book():
    b_id = int(input('ID: '))
    title = input('Title: ')
    price = float(input('Price: '))
    record = {'BookID': b_id, 'Title': title, 'Price': price}
    with open('books.dat', 'ab') as file:
        pickle.dump(record, file)

def search_book(target_id):
    found = False
    try:
        with open('books.dat', 'rb') as file:
            while True:
                record = pickle.load(file)
                if record['BookID'] == target_id:
                    print(record)
                    found = True
    except EOFError:
        if not found:
            print('Not Found')
    except FileNotFoundError:
        print('Database missing')
