def PushSession(stack, sessions):
    for session in sessions:
        if session['duration'] > 30:
            stack.append(session['IP'])
            print(f"Pushed {session['IP']}")

def PopSession(stack):
    if len(stack) == 0:
        print('Stack Empty Underflow')
        return None
    else:
        ip = stack.pop()
        print(f"Terminating session: {ip}")
        return ip

